21: export const useActivityHistory = (
22:   id: string,
23:   pageSize = 5,
24: ): AxiosSWRInfiniteResponse<GetActivityHistoryByTargetIdResponse> => {
25:   return useAxiosSWRInfinite<GetActivityHistoryByTargetIdResponse>(
26:     (page, previous) => {
27:       if (previous && !previous?.paginationDetails?.nextToken) return null;
28: 
29:       const params: GetActivityHistoryByIdRequestData = {
30:         targetId: id,
31:         pageSize,
32:       };
33: 
34:       if (page !== 0 && previous?.paginationDetails.nextToken) {
35:         params.paginationToken = previous.paginationDetails.nextToken;
36:       }
37: 
38:       return `${config.activitiesApiUrl}/activityhistory?${stringify(params)}`;
39:     },
40:     {
41:       onErrorRetry: /* istanbul ignore next: unreachable in test suite */ (
42:         error,
43:         key,
44:         config,
45:         revalidate,
46:         { retryCount },
47:       ) => {
48:         if (error.response?.status === 404) return;
49:         if (retryCount >= 3) return;
50: 
51:         const count = Math.min(retryCount, 8);
52:         const timeout =
53:           ~~((Math.random() + 0.5) * (1 << count)) * config.errorRetryInterval;
54:         setTimeout(() => revalidate({ retryCount }), timeout);
55:       },
56:     },
57:   );
58: };

